    @Override
    public void setupAnim(Entity entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {

        float id2;
        float f4;
        float f3;
        float GD;
        float GS;
        EntityCrux parasite = (EntityCrux)entity;
        this.jointLL0.xRot = 0.0f;
        this.jointLL1.xRot = 0.0f;
        this.jointLL2.xRot = 0.0f;
        this.jointRL0.xRot = 0.0f;
        this.jointRL1.xRot = 0.0f;
        this.jointRL2.xRot = 0.0f;
        this.jointLA0.zRot = 0.0f;
        this.jointLA0.xRot = 0.0f;
        this.jointLA1.yRot = 0.0f;
        this.jointLA1.xRot = 0.0f;
        this.jointRA0.zRot = 0.0f;
        this.jointRA0.xRot = 0.0f;
        this.jointRA1.yRot = 0.0f;
        this.jointRA1.xRot = 0.0f;
        this.jointM.xRot = 0.0f;
        this.jointDZ1.zRot = 0.0f;
        this.jointDZ2.zRot = 0.0f;
        this.jointDZ3.zRot = 0.0f;
        this.jointDZ4.zRot = 0.0f;
        this.jointDZ5.zRot = 0.0f;
        this.jointDZ6.zRot = 0.0f;
        this.jointDZ7.zRot = 0.0f;
        this.jointDZ8.zRot = 0.0f;
        this.jointDX1.xRot = 0.0f;
        this.jointH.xRot = headPitch * 0.016f;
        this.jointH.yRot = netHeadYaw * -0.016f;
        this.bodyuy.yRot = 0.0f;
        this.mainbody.y = 0.0f;
        boolean canR = parasite.getBack();
        this.jointDZ7.visible = !(!canR);
        this.jointDZ4.visible = !(!canR);
        this.jointDX1.visible = !(!canR);
        this.jointDZ8.visible = !(!canR);
        this.dec8.visible = !(!canR);
        this.body7.visible = !(!canR);
        this.body6.visible = !(!canR);
        this.body5.visible = !(!canR);
        this.body4.visible = !(!canR);
        this.body3.visible = !(!canR);
        this.body2.visible = !(!canR);
        this.body1.visible = !(!canR);
        byte i = parasite.getParasiteStatus();
        float f1 = Mth.cos((float)(ageInTicks * 0.15f)) * 0.0512f;
        float f2 = -1.0f * Mth.cos((float)(ageInTicks * 0.14613f)) * 0.05181f;
        this.body1.x = f1;
        this.body1.y = f2;
        this.body2.x = f2;
        this.body2.y = f1;
        f1 = Mth.cos((float)(ageInTicks * 0.135f)) * 0.06512f;
        this.body3.x = f2 = -1.0f * Mth.cos((float)(ageInTicks * 0.114613f)) * 0.045181f;
        this.body3.y = f1;
        this.body4.x = f1;
        this.body4.y = f2;
        this.body5.x = f1;
        this.body5.y = f2;
        if (i == 0) {
            if (!parasite.getStillAni()) {
                GS = 1.1f;
                GD = 0.7f;
                this.swingX(this.jointLL0, 0.3f * GS, 0.7f * GD, 1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointRL0, 0.3f * GS, 0.7f * GD, -1, 1.0f, 0.2f, limbSwing, limbSwingAmount);
                this.swingX(this.jointLL1, 0.3f * GS, 0.5f * GD, 1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.swingX(this.jointRL1, 0.3f * GS, 0.5f * GD, -1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.swingX(this.jointLL2, 0.3f * GS, 0.8f * GD, 1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.swingX(this.jointRL2, 0.3f * GS, 0.8f * GD, -1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.moveY(this.mainbody, 0.6f * GS, 1, limbSwing, limbSwingAmount, 0.1f);
                this.swingZ(this.jointLA0, 0.3f * GS, 0.5f * GD, 1, 0.2f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointLA1, 0.3f * GS, 0.2f * GD, -1, -1.5f, 0.0f, limbSwing, limbSwingAmount);
                this.swingZ(this.jointRA0, 0.3f * GS, 0.5f * GD, 1, 0.2f, 0.0f, limbSwing, limbSwingAmount);
                this.swingY(this.jointRA1, 0.3f * GS, 0.2f * GD, -1, -1.5f, 0.0f, limbSwing, limbSwingAmount);
            }
            this.jointM.xRot = f1 = Mth.cos((float)(ageInTicks * 0.15f)) * 0.12f;
            f1 = Mth.cos((float)(ageInTicks * 0.0514f)) * 0.23f;
            f2 = -1.0f * Mth.cos((float)(ageInTicks * 0.0613f)) * 0.181f;
            f3 = Mth.cos((float)(ageInTicks * 0.04145f)) * 0.25f;
            f4 = -1.0f * Mth.cos((float)(ageInTicks * 0.04135f)) * 0.1772f;
            float f5 = Mth.cos((float)(ageInTicks * 0.05133f)) * 0.199f;
            this.jointDZ1.zRot = f1;
            this.jointDZ2.zRot = f5;
            this.jointDZ3.zRot = f2;
            this.jointDZ4.zRot = f3;
            this.jointDZ5.zRot = f2;
            this.jointDZ6.zRot = f4;
            this.jointDZ7.zRot = f5;
            this.jointDZ8.zRot = f1;
            this.jointDX1.xRot = f4;
        } else if (i == 1 || i == 2) {
            if (!parasite.getStillAni()) {
                GS = 0.99f;
                GD = 0.7f;
                this.swingX(this.jointLL0, 0.3f * GS, 1.1f * GD, 1, 1.0f, 0.5f, limbSwing, limbSwingAmount);
                this.swingX(this.jointRL0, 0.3f * GS, 1.1f * GD, -1, 1.0f, 0.5f, limbSwing, limbSwingAmount);
                this.swingX(this.jointLL1, 0.3f * GS, 0.5f * GD, 1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.swingX(this.jointRL1, 0.3f * GS, 0.5f * GD, -1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.swingX(this.jointLL2, 0.3f * GS, 0.8f * GD, 1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.swingX(this.jointRL2, 0.3f * GS, 0.8f * GD, -1, 0.0f, 0.1f, limbSwing, limbSwingAmount);
                this.moveY(this.mainbody, 0.6f * GS, 1, limbSwing, limbSwingAmount, 0.15f);
                this.swingZ(this.jointLA0, 0.3f * GS, 1.0f * GD, 1, 0.2f, -0.5f, limbSwing, limbSwingAmount);
                this.swingY(this.jointLA1, 0.3f * GS, 0.9f * GD, -1, -1.5f, 0.0f, limbSwing, limbSwingAmount);
                this.jointLA1.xRot = -0.5f;
                this.swingZ(this.jointRA0, 0.3f * GS, 1.0f * GD, 1, 0.2f, 0.5f, limbSwing, limbSwingAmount);
                this.swingY(this.jointRA1, 0.3f * GS, 0.9f * GD, -1, -1.5f, 0.0f, limbSwing, limbSwingAmount);
                this.jointRA1.xRot = 0.5f;
            }
            this.jointM.xRot = f1 = Mth.cos((float)(ageInTicks * 0.45f)) * 0.2f;
            f1 = Mth.cos((float)(ageInTicks * 0.0514f)) * 0.23f;
            f2 = -1.0f * Mth.cos((float)(ageInTicks * 0.0613f)) * 0.181f;
            f3 = Mth.cos((float)(ageInTicks * 0.04145f)) * 0.25f;
            f4 = -1.0f * Mth.cos((float)(ageInTicks * 0.04135f)) * 0.1772f;
            float f5 = Mth.cos((float)(ageInTicks * 0.05133f)) * 0.199f;
            this.jointDZ1.zRot = f1;
            this.jointDZ2.zRot = f5;
            this.jointDZ3.zRot = f2;
            this.jointDZ4.zRot = f3;
            this.jointDZ5.zRot = f2;
            this.jointDZ6.zRot = f4;
            this.jointDZ7.zRot = f5;
            this.jointDZ8.zRot = f1;
            this.jointDX1.xRot = f4;
        }
        float id = parasite.getAttackTimerM();
        if (id > 0.0f) {
            this.jointRA0.xRot -= Math.min(0.8f, id);
            this.jointRA1.yRot = (float)((double)this.jointRA1.yRot - Math.min(0.8, (double)id));
            this.jointLA0.xRot -= Math.min(0.8f, id);
            this.jointLA1.yRot = (float)((double)this.jointLA1.yRot + Math.min(0.8, (double)id));
        }
        if ((id2 = parasite.getAttackTimerR()) > 0.0f) {
            this.bodyuy.yRot = (float)((double)this.bodyuy.yRot - Math.min(1.1, (double)id2));
            this.jointRA1.xRot = (float)((double)this.jointRA1.xRot + Math.min(2.8, (double)id2));
        }
    
    }

